        return [[8 if j in range(5) else 3 for j in range(15)] for _ in range(15)]
    return [r[::-1] for r in grid]"},{"nl":"When the input is 15x15, fill columns 0 through 4 with 8 and columns 5 through 14 with 3; otherwise transpose.","code":"def transform(grid):
    h=len(grid); w=len(grid[0]) if h else 0
